/**
 * Audio paths for the keynote film. Files are generated by
 *   python3 scripts/make_audio.py public/audio 34.9        (original SFX)
 *   python3 scripts/make_audio_vertical.py public/audio    (slam, boom, glass_flip, swipe, …)
 *   python3 scripts/make_audio_film.py public/audio        (orbit, flip, text_in, mouse_down,
 *                                                            trackpad_tap, sub_drop, heartbeat,
 *                                                            cursor_whir + music_film.wav)
 * public/audio is git-ignored, so run all three before rendering.
 *
 * Existence check (no fs at render time): every stem in SFX_STEMS must have a matching
 * public/audio/sfx_<stem>.wav. Verify from promo/ with
 *   for s in $(grep -o '"[a-z_0-9]*"' <<< "$(sed -n '/SFX_STEMS = \[/,/\]/p' src/film/contract.ts)" | tr -d '"'); do
 *     [ -f public/audio/sfx_$s.wav ] || echo missing $s; done
 * Use `isKnownStem` to guard cue lists at build time (type-level + runtime membership).
 */
import { SFX_STEMS } from "./contract";

export const filmSfx = (stem: string) => `audio/sfx_${stem}.wav`;
export const MUSIC_FILM = "audio/music_film.wav";

const KNOWN = new Set<string>(SFX_STEMS);
/** True when `stem` is one of the contract's SFX stems (i.e. a file the audio scripts produce). */
export const isKnownStem = (stem: string) => KNOWN.has(stem);
